const _pidioMaterial = /peluche|satin|sat[ií]n/.test(_txtLead);
const _ESPECIFICA = /^pantuflas mono (peluche|satin)$/i;
const _GENERICA = /^pantuflas( mono)?$/i;
const _antes = productos.slice();
if (_pidioMaterial) {
  // Cobertura por material, DETERMINÍSTICA: se decide por el TEXTO del lead, no por lo que
  // emitió el LLM (inconsistente, y por eso faltaban assets — Oscar 26/8).
  const _esPeluche = /peluche/.test(_txtLead);
  if (_esPeluche) {
    // Peluche: SOLO la ficha de peluche + el video general, SIN catálogo (el catálogo es de
    // diseños de satín y no aplica a la de peluche). Lista fija.
    productos = productos.filter(p => !/pantufla/i.test(p) || /peluche/i.test(p));
    if (!productos.some(p => /^pantuflas mono peluche$/i.test(p))) productos.push('pantuflas mono peluche');
    productos.push('pantuflas video');
  } else {
    // Satín: surtido completo CON catálogo. Se garantiza el genérico "pantuflas" (trae
    // infografía + catálogo + ficha de satín + video); el EXISTS de W3 deduplica, sin repes.
    if (!productos.some(p => _GENERICA.test(p))) productos.push('pantuflas');
  }
} else if (productos.some(p => _GENERICA.test(p))) {
  // no nombró material: se descartan los específicos que el agente agregó de más, para que
  // siga viendo el surtido completo con su catálogo.
  productos = productos.filter(p => !_ESPECIFICA.test(p));
}

