const _ESPECIFICA = /^pantuflas mono (peluche|satin)$/i;
const _GENERICA = /^pantuflas( mono)?$/i;
const _antes = productos.slice();
if (_mencionaPantufla || _pidioMaterial) {
  // Cobertura de pantuflas, DETERMINÍSTICA: se decide por el TEXTO del lead, no por lo que
  // emitió el LLM (inconsistente, y por eso faltaban assets — Oscar 26/8).
  const _esPeluche = /peluche/.test(_txtLead);
  if (_esPeluche) {
    // Peluche: SOLO la ficha de peluche + el video general, SIN catálogo (el catálogo es de
    // diseños de satín y no aplica a la de peluche). Lista fija.
    productos = productos.filter(p => !/pantufla/i.test(p) || /peluche/i.test(p));
    if (!productos.some(p => /^pantuflas mono peluche$/i.test(p))) productos.push('pantuflas mono peluche');
    productos.push('pantuflas video');
  } else {
    // Satín / normal / cerrada: surtido completo CON catálogo. Se sacan los mono-específicos
